// THE PLAY ARCHIVE: refined cinematic 1-screen home.
let tpFilter='전체',tpPage=0,tpRecordsOpen=false;
let tpRecent='';try{tpRecent=localStorage.getItem('tp_recent_game')||''}catch(err){}
const tpPhotos=['data:image/webp;base64,','data:image/webp;base64,','data:image/webp;base64,','data:image/webp;base64,'];
const tpIcons={
  search:`<svg viewBox="0 0 24 24"><circle cx="11" cy="11" r="7"></circle><path d="m16 16 5 5"></path></svg>`,
  bookmark:`<svg viewBox="0 0 24 24"><path d="M5 4h14v17l-7-5-7 5z"></path></svg>`,
  user:`<svg viewBox="0 0 24 24"><circle cx="12" cy="8" r="4"></circle><path d="M3.5 21c0-4.5 3-7 8.5-7s8.5 2.5 8.5 7"></path></svg>`
};
function tpGames(){
 if(tpFilter==='전체')return [...osGames];
 if(tpFilter==='더 지니어스')return osGames.filter(n=>entries.some(e=>e.name===n&&e.group.startsWith('지니어스')));
 if(tpFilter==='데블스 플랜')return osGames.filter(n=>entries.some(e=>e.name===n&&e.group.startsWith('데블스')));
 return osGames.filter(n=>(genreLookup[n]==='memory'||['큐브 세기','네모 세기','기사의 여행'].includes(n)));
}
function tpSetFilter(x){tpFilter=x;tpPage=0;showHome()}
function tpMovePage(n){const pages=Math.max(1,Math.ceil(tpGames().length/4));tpPage=(tpPage+n+pages)%pages;showHome()}
function tpBegin(name){if(!supported[name])return;tpRecent=name;try{localStorage.setItem('tp_recent_game',name)}catch(e){}start(name)}
function tpShowRecords(){tpRecordsOpen=true;showHome()}
function tpHideRecords(){tpRecordsOpen=false;showHome()}
function tpModal(){if(!tpRecordsOpen)return '';return `<div class="tp-stats-dialog" role="dialog" aria-modal="true" aria-label="플레이 기록"><div class="tp-stats-content"><h2>내 플레이 기록</h2><p>완료한 게임: <b>${stat.games||0}회</b></p><p>승리: <b>${stat.wins||0}회</b></p><p>승률: <b>${stat.games?Math.round(stat.wins/stat.games*100):0}%</b></p><p style="font-size:12px;line-height:1.7;color:#bba996">현재 브라우저에 저장된 완료 결과 기준입니다. 진행 중인 판을 이어 하는 기능은 제공하지 않습니다.</p><button onclick="tpHideRecords()">닫기</button></div></div>`}
const tpOriginalShowHome=showHome;
showHome=function(keepFocus=false){
 const num=Object.keys(supported).length;
 const filtered=tpGames(),pages=Math.max(1,Math.ceil(filtered.length/4));tpPage=Math.min(tpPage,pages-1);
 const list=filtered.slice(tpPage*4,tpPage*4+4),count=Object.keys(supported).length;
 const recentOk=!!tpRecent&&!!supported[tpRecent],rdesc=recentOk?(gameProfiles[tpRecent]?.genre||'마지막 선택한 게임'):'아직 선택한 게임이 없습니다';
 const filterNames=['전체','더 지니어스','데블스 플랜','퍼즐·기타'];
 const firstArt=['흑과 백','인디언 포커','결! 합!','십이장기'];
 const artFor=n=>{const idx=firstArt.indexOf(n);return idx>=0?tpPhotos[idx]:(cinemaThumbs[n]||gamePosters[n]||'')};
 const total=new Set(entries.map(x=>x.name)).size;
 const catalog=entries.filter(x=>(view==='all'||view===x.group||view==='playable'&&x.playable)&&(x.name.includes(search)||x.group.includes(search)));
 const modal=archiveOpen?`<div class="os-modal-backdrop" onclick="closeLibrary()" role="presentation"></div>
    <section class="os-modal" role="dialog" aria-modal="true" aria-label="전체 게임 아카이브">
      <header class="os-modal-heading"><div><small>THE COMPLETE COLLECTION</small><h2>게임 아카이브 <span>${total}종</span></h2></div><button class="os-close" onclick="closeLibrary()" aria-label="아카이브 닫기">✕</button></header>
      <div class="os-modal-tools"><div class="os-season-tabs">${[['all','전체'],['playable','플레이 가능'],...Object.keys(groups).map(x=>[x,x])].map(([key,label])=>`<button class="${view===key?'on':''}" onclick="setView('${key}')">${label}</button>`).join('')}</div><label class="os-search-wrapper"><span>⌕</span><input id="query" type="search" aria-label="게임 검색" placeholder="게임 이름 검색" value="${txt(search)}" oninput="searchGames(this.value)"></label></div>
      <div class="os-results-count">검색 결과 ${catalog.length}회 등장 <span>· 현재 플레이 가능 ${num}종 · 나머지는 규칙 구현 중</span></div>
      <div class="os-results">${catalog.map(x=>`<div class="os-result"><span class="os-result-symbol">${x.playable?(rzMarks[x.name]||'✦'):'◇'}</span><div class="os-result-info"><strong>${txt(x.name)}</strong><small>${txt(x.group)} · ${x.type==='main'?'메인매치':'데스·결승전'}</small></div>${x.playable?`<button onclick="start('${x.name}')">플레이 ↗</button>`:'<span class="os-locked">준비 중</span>'}</div>`).join('')||'<div class="os-no-results">검색 결과가 없습니다.</div>'}</div>
      <footer class="os-modal-footer">비공식 개인용 연습 프로젝트 · 실제 방송 규칙과 차이가 있을 수 있습니다 · 전 게임 완전 재현 아님</footer>
    </section>`:'';
 $('#app').innerHTML=`<main class="tp-home" style="--tp-room:url('data:image/webp;base64,')" aria-label="더 플레이 아카이브 게임 홈">
   <nav class="tp-nav" aria-label="사이트 탐색"><div class="tp-nav-left">
    <button class="tp-menu" onclick="openLibrary()" aria-label="게임 목록 열기">☰</button>
    <button class="tp-nav-btn tp-active" onclick="home()">게임 플레이</button>
    <button class="tp-nav-btn" onclick="openLibrary()">게임 목록</button>
    <button class="tp-nav-btn" onclick="openLibrary()">아카이브</button>
    <button class="tp-nav-btn" onclick="tpShowRecords()">기록실</button>
   </div><span class="tp-nav-mark">THE PLAY ARCHIVE</span>
   <div class="tp-nav-right">
    <button class="tp-icon-btn" aria-label="검색" onclick="openLibrary()">${tpIcons.search}</button>
    <button class="tp-icon-btn" aria-label="최근 게임" onclick="${recentOk?`tpBegin('${tpRecent}')`:'openLibrary()'}">${tpIcons.bookmark}</button>
    <button class="tp-icon-btn" aria-label="내 기록" onclick="tpShowRecords()">${tpIcons.user}</button>
   </div></nav>
   <div class="tp-content">
    <header class="tp-hero"><div class="tp-eyebrow">THE PRIVATE GAME COLLECTION</div><h1>THE PLAY ARCHIVE</h1><p class="tp-subtitle">CHOOSE YOUR GAME &nbsp; · &nbsp; CHALLENGE THE MIND</p></header>
    <section class="tp-shelf"><div class="tp-shelf-heading"><div class="tp-shelf-title"><span></span><strong>게임 컬렉션</strong><small>${filtered.length} / ${count}</small></div>
      <div class="tp-filters" role="group" aria-label="게임 분류">${filterNames.map(v=>`<button class="tp-filter" aria-pressed="${v===tpFilter}" onclick="tpSetFilter('${v}')">${v}</button>`).join('')}</div></div>
     <div class="tp-gallery" aria-label="게임 선택">${list.map((n,i)=>`<button class="tp-game" data-featured="${tpPage===0&&i===0&&tpFilter==='전체'}" onclick="tpBegin('${n}')" aria-label="${txt(n)} 시작하기"><span class="tp-image" style="background-image:url('${artFor(n)}')"></span><span class="tp-game-text"><strong>${txt(n)}</strong><small>${txt(gameProfiles[n]?.genre||'전략 게임')}</small></span><span class="tp-play-icon">▶</span></button>`).join('')}</div>
    </section>
    <div class="tp-deck-nav"><button onclick="tpMovePage(-1)" aria-label="이전 게임">‹</button><span>${tpPage+1} / ${pages}</span><button onclick="tpMovePage(1)" aria-label="다음 게임">›</button></div>
    <footer class="tp-bottom">
      <section class="tp-status"><span class="tp-status-icon">◷</span><div class="tp-status-copy"><strong>최근 플레이</strong><span>${recentOk?txt(tpRecent)+' · '+txt(rdesc):'게임을 선택해 첫 대결을 시작하세요.'}</span></div>${recentOk?`<span class="tp-recent-image" style="background-image:url('${artFor(tpRecent)}')"></span>`:''}<button onclick="${recentOk?`tpBegin('${tpRecent}')`:'openLibrary()'}">${recentOk?'다시 플레이':'게임 선택'}</button></section>
      <section class="tp-status"><span class="tp-status-icon">♜</span><div class="tp-status-copy"><strong>내 기록</strong><span class="tp-records">완료 ${stat.games||0}회 &nbsp; | &nbsp; 승리 ${stat.wins||0}회 &nbsp; | &nbsp; 승률 <strong>${stat.games?Math.round(stat.wins/stat.games*100):0}%</strong></span></div><button aria-label="자세한 플레이 기록" onclick="tpShowRecords()">›</button></section>
    </footer>
   </div>${modal}${tpModal()}
  </main>`;
 if(keepFocus){const inp=$('#query');if(inp){inp.focus();try{inp.setSelectionRange(inp.value.length,inp.value.length)}catch(e){}}}
};

showHome();
